assert len(SHAPES)==12
artmap={};manifest=[]
for slug,inner in SHAPES.items():
 svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="100" height="100" aria-hidden="true"><ellipse cx="50" cy="95" rx="32" ry="3" fill="#607883" opacity=".10"/>'+inner+'</svg>'
 file=art/(slug+'.svg');file.write_text(svg)
 artmap[slug.replace('-',' ')]=svg
 manifest.append({'id':'organic45:'+slug,'path':str(file.relative_to(root)),'sha256':hashlib.sha256(svg.encode()).hexdigest()})
(root/'client/src/organic-art-v45.js').write_text('export const ORGANIC_ART_V45 = '+json.dumps(artmap,separators=(',',':'))+';\n')
(root/'shared/v45-art-manifest.json').write_text(json.dumps({'release':'V45','icons':manifest},indent=2)+'\n')
print('created',len(SHAPES),'individually drawn safe vector icons')
